function storageBatchGroup(batch){if(Number(batch.balance_grams)<=0)return 'empty';if(!batch.verified)return 'receiving';if(['pantry','fridge'].includes(batch.storage_kind))return batch.storage_kind;return 'receiving'}
function storageKg(grams){return new Intl.NumberFormat('ru-RU',{maximumFractionDigits:3}).format(Number(grams)/1000)+' кг'}
function storageCropIcon(crop){return /морков/i.test(crop)?'🥕':/карто|potato/i.test(crop)?'🥔':/томат|помид|tomato/i.test(crop)?'🍅':/огур|cucumber/i.test(crop)?'🥒':/баклаж/i.test(crop)?'🍆':/капуст/i.test(crop)?'🥬':/перец/i.test(crop)?'🫑':/лук/i.test(crop)?'🧅':/редис/i.test(crop)?'🌱':/ягод|клубник/i.test(crop)?'🍓':'🌿'}
function storageCrate(batch){const expired=batch.expires_at&&Date.parse(batch.expires_at)<=Date.now(),reserved=Number(batch.reserved_grams)||0;return `<button class="storage-crate ${expired?'storage-expired':''}" onclick="showPassport('${batch.id}')" aria-label="${esc(batch.crop)} · ${storageKg(batch.balance_grams)} · открыть паспорт партии"><span class="storage-produce" aria-hidden="true"><i>${storageCropIcon(batch.crop)}</i><i>${storageCropIcon(batch.crop)}</i><i>${storageCropIcon(batch.crop)}</i></span><span class="crate-label"><b>${esc(batch.crop)}</b><strong>${storageKg(batch.balance_grams)}</strong></span>${reserved?`<small>В резерве: ${storageKg(reserved)}</small>`:''}${expired?'<small class="storage-warning">Срок истёк · нужен осмотр</small>':`<small>${batch.expires_at?'До '+new Date(batch.expires_at).toLocaleDateString('ru-RU'):'Срок уточняется'}</small>`}</button>`}
function storageShelves(batches){const shelves=[];for(let i=0;i<Math.max(6,batches.length);i+=2)shelves.push(`<div class="storage-shelf">${batches.slice(i,i+2).map(storageCrate).join('')}</div>`);return shelves.join('')}
warehousePage=function(){if(!account)return heading('Мой склад','Войдите, чтобы увидеть свой урожай.')+'<button class="btn" onclick="profile()">Войти</button>';const current=selectedFarmCity(),batches=batchData.filter(b=>Number(b.balance_grams)>0&&(!b.city_id||b.city_id===current)),pantry=batches.filter(b=>storageBatchGroup(b)==='pantry'),fridge=batches.filter(b=>storageBatchGroup(b)==='fridge'),receiving=batches.filter(b=>storageBatchGroup(b)==='receiving');return `<section class="storage-room"><div class="storage-room-heading"><a href="#home">← Хозяйство</a><h1>Мой склад</h1><p>${esc(neighborCity(current)?.name||'')} · Нажмите на ящик, чтобы открыть паспорт урожая</p></div><div class="storage-room-interior"><section class="pantry-cabinet"><div class="storage-cabinet-title"><span>🪵</span><h2>Кладовая</h2><small>${storageKg(pantry.reduce((s,b)=>s+Number(b.balance_grams),0))}</small></div><div class="wood-shelves">${storageShelves(pantry)}</div>${!pantry.length?'<p class="storage-empty-note">Полки пока пустые.<br>Здесь появится принятый в кладовую урожай.</p>':''}</section><section class="fridge-cabinet"><div class="storage-cabinet-title"><span>❄️</span><h2>Холодильник</h2><small>${storageKg(fridge.reduce((s,b)=>s+Number(b.balance_grams),0))}</small></div><div class="fridge-glass"><div class="fridge-light"></div>${storageShelves(fridge)}<span class="fridge-handle" aria-hidden="true"></span></div>${!fridge.length?'<p class="storage-empty-note">Холодильник пока пустой.<br>Сюда попадают партии с подтверждённым хранением в холоде.</p>':''}</section></div><p class="storage-room-note">Вес включает зарезервированный урожай. Место хранения и срок подтверждает ферма при приёмке. Температура без датчика не показывается.</p>${receiving.length?`<section class="storage-receiving"><h2>🧺 Ожидает размещения</h2><p>Урожай уже записан, но ферма ещё не подтвердила место хранения.</p><div class="storage-receiving-crates">${receiving.map(storageCrate).join('')}</div></section>`:''}<div class="storage-room-actions"><button class="btn" onclick="basketForm()">🧺 Собрать корзину домой</button><a class="btn light" href="#lifecycle">Хранение и доставка</a><button class="btn light" onclick="newBatch()">＋ Записать сбор</button></div></section>`};
